/* Wissen › Wiederholung, KW 48/2026. */
WDH_woche({"kw": "2026-W48", "von": "2026-11-23", "bis": "2026-11-29", "plan": {"mo": "w48-nack", "mi": "w48-rad"}, "einheiten": [{"id": "w48-nack", "titel": "Nicht-spezifischer Nackenschmerz", "art": "kb", "kb": "WS05", "min": 11, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Nicht-spezifisch heißt: Schmerz im Nacken, oft bis in die Schulter und den Hinterkopf, ohne Hinweis auf Fraktur, [[Myelopathie|myelo]], Radikulopathie, Gefäß-, Tumor- oder Entzündungsursache. Grundlage in Deutschland ist die [[DEGAM-S3-Leitlinie 2025|degam]]."]}, {"l": ["Häufigkeit: 45,7 % der Erwachsenen in Deutschland hatten in den letzten 12 Monaten Nackenschmerz (RKI BURDEN 2020). Weltweit waren es 2020 rund 203 Millionen Betroffene, für 2050 werden etwa 269 Millionen erwartet (GBD 2021).", "Frauen sind häufiger betroffen, am häufigsten zwischen 45 und 74 Jahren.", "Eine gefährliche Ursache steckt bei unter 1 % dahinter. Genau die soll man aber nicht übersehen, siehe Abschnitt 3.", "Ursachen sind meist mehrere zugleich: viel Bildschirmarbeit, wenig Kraft und Ausdauer der Nackenmuskeln, Stress, schlechter Schlaf."]}]}, {"t": "2. Einteilung und Verlauf", "b": [{"tab": [["Akut", "0–3 Wochen (DEGAM). Die JOSPT-Leitlinie zählt alles unter 6 Wochen als akut."], ["Subakut", "4–12 Wochen"], ["Chronisch", "über 12 Wochen"]], "p": ["Die [[JOSPT-Einteilung|jospt]] trennt zusätzlich vier klinische Bilder: mit Mobilitätsdefizit, mit Koordinationsstörung (oft nach Schleudertrauma), mit Kopfschmerz und mit ausstrahlendem Schmerz. Die Gruppe steuert die Behandlung."]}, {"bars": [["Schmerz am Anfang", 64, "von 100 im Mittel zu Beginn"], ["Nach 6,5 Wochen", 35, "deutlicher Rückgang in den ersten Wochen"], ["Nach 12 Monaten", 42, "die Kurve flacht ab, viele behalten leichte Beschwerden"]]}, {"p": ["Die Werte stammen aus der Metaanalyse von Hush 2011. 50–75 % haben 1–5 Jahre später wieder Nackenschmerz. Ungünstig für den Verlauf sind vor allem psychosoziale Faktoren: starke Schmerzen, hohe Beeinträchtigung, Katastrophisieren, Angst. Nach einem Schleudertrauma gelten NRS ab 6, NDI über 30 % und ein Katastrophisierungswert (PCS) ab 20 als Warnwerte."], "merk": "Der Nacken bessert sich in den ersten 6 Wochen meist deutlich, Rückfälle sind aber häufig. Training senkt das Risiko."}]}, {"t": "3. Red Flags zuerst", "b": [{"tab": [["Trauma", "Verdacht auf Fraktur nach Unfall: [[Canadian C-Spine Rule|ccsr]] anwenden, ärztlich"], ["Myelopathie", "Gangunsicherheit, ungeschickte Hände, beidseitige Missempfindungen. [[Cook-Cluster|cook]] nutzen"], ["Gefäße", "Schwindel, Doppelbilder, Sprach- oder Schluckstörung, Fallattacken, Nystagmus, neu einsetzender heftiger Kopf- oder Nackenschmerz ([[IFOMPT-Rahmen|ifompt]]). Sofort ärztlich"], ["Infektion, Entzündung", "Fieber, Nackensteife"], ["Tumor", "Tumoranamnese, Gewichtsverlust, Nachtschmerz"]], "merk": "Vor jeder Behandlung der HWS Gefäß- und Myelopathiezeichen abfragen. Kein einzelner Test schließt eine Dissektion aus, entscheidend ist die Anamnese."}]}, {"t": "4. Befund und Abgrenzung", "b": [{"l": ["Aktive Beweglichkeit von HWS und BWS, dazu Schulterblattkontrolle und Kraft für Nacken und Schulter.", "Bei Kopfschmerz der [[Flexions-Rotations-Test|frt]]: positiv bei unter 32° oder mehr als 10° unter dem Normalwert von etwa 44°.", "Ausdauer der tiefen Halsbeuger: Norm bei Männern etwa 39 s, bei Frauen etwa 29 s, mit großer Streuung (Domenech 2011).", "Bei Armsymptomen: Neurologie, Spurling-Test, ULTT. Dann ist es eher eine zervikale Radikulopathie."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/kopf-ccft.webp", "t": "Kraniozervikaler Flexionstest.", "c": "Hakenlage, Luftkissen unter dem Nacken auf 20 mmHg. Kleines Ja-Nicken, jede Stufe 10 s halten, der SCM soll nicht mitarbeiten. Dieselbe Bewegung ist die Grundübung für die tiefen Halsbeuger."}]}, {"tab": [["Zervikale Radikulopathie", "Armschmerz im Dermatom, Ausfälle. Spurling, Distraktion, ULTT, Neurologie"], ["Zervikale Myelopathie", "Gang unsicher, Hände ungeschickt, beidseits. Cook-Cluster, ärztlich"], ["Schleudertrauma", "Unfallhergang. Anamnese, Canadian C-Spine Rule"], ["Zervikogener Kopfschmerz", "einseitig, durch Nackenbewegung ausgelöst. Flexions-Rotations-Test"], ["Dissektion", "neuer heftiger Schmerz, Hirnnervenzeichen. Sofort ärztlich"], ["Schulter", "Schmerz bei Armbewegung, nicht bei HWS-Bewegung. Schultertests"]]}, {"l": ["Messen im Verlauf: [[NDI|ndi]] (spürbar etwa 7,5 von 50 Punkten), NPRS (1,3–2 Punkte), PSFS (etwa 2 Punkte).", "Bildgebung nur bei Warnzeichen (DEGAM, Grad A). Sonst nach 4–6 Wochen neu einschätzen."], "merk": "Ohne Warnzeichen kein Röntgen und kein MRT. Der Befund steuert die Übungen, nicht das Bild."}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"p": ["Die DEGAM-Leitlinie stellt aktive Behandlung klar vor passive. Körperliche Aktivität und Bewegungstherapie bei chronischem Nackenschmerz bekommen Grad A, Aufklärung und Wärme in Eigenanwendung Grad B. Manuelle Therapie, Weichteiltechniken und Akupunktur sind nur „kann“, und auch das nur zusammen mit aktivierenden Maßnahmen."]}, {"l": ["Krafttraining für Nacken, Schultergürtel und Arme ist gut belegt (Cochrane, Gross 2015).", "Dosis: [[Andersen 2012|andersen]] zeigte bei 447 Büroangestellten, dass 1 Stunde Nacken-Schulter-Training pro Woche über 20 Wochen wirkt, egal ob am Stück oder aufgeteilt. Schon 2 Minuten Theraband täglich an 5 Tagen bringen etwas.", "Übungsform: Kraft, Motorkontrolle, Yoga, Pilates und Tai Chi wirken etwa gleich gut ([[de Zoete 2021|dezoete]]). Eine Übersicht über 25 Reviews kommt zum selben Schluss und findet für Krafttraining allein bei der Beeinträchtigung keinen klaren Effekt ([[Rasmussen-Barr 2023|rasmussen]]).", "Thorakale Manipulation oder HWS-Mobilisation: kurzfristig weniger Schmerz, immer als Ergänzung zu Übungen.", "Vorbeugung: Übungen senken neue Episoden deutlich (OR 0,32, de Campos 2018). Ergonomieprogramme allein tun das nicht.", "Massage: akut nicht. Bei chronischem Nackenschmerz nur hoch dosiert (60 Minuten) und mit Aktivierung (Sherman 2014).", "Zervikogener Kopfschmerz: manuelle Therapie der oberen HWS plus Training der tiefen Halsbeuger mit niedriger Last, etwa 6 Wochen, der Effekt hielt nach 12 Monaten noch (Jull 2002)."]}, {"tab": [["Nicht empfohlen (DEGAM, Grad B)", "Traktion, Elektrotherapie, Laser, Kinesiotape"], ["Ebenfalls nicht empfohlen", "Ultraschall, Halskrause, Fango und Rotlicht als Verordnung, passive Maßnahmen allein"]], "merk": "Welche Übungsform, ist fast egal. Wichtig ist, dass der Patient regelmäßig trainiert, mindestens etwa 1 Stunde pro Woche."}, {"p": ["Ein Widerspruch: Die JOSPT-Leitlinie von 2017 gibt Laser, Traktion und Dry Needling bei chronischem Mobilitätsdefizit Grad B. DEGAM, KNGF und OPTIMa raten davon ab. Für Deutschland gilt die neuere DEGAM-Leitlinie."]}]}, {"t": "6. Was neu ist", "b": [{"l": ["Die JOSPT-Leitlinie zum Nackenschmerz wird überarbeitet, die Neufassung ist noch nicht erschienen. Bis dahin gilt die Revision von 2017.", "[[Peters 2025|peters]] hat 19 internationale Leitlinien verglichen. Alle hochwertigen empfehlen Mobilisation oder Manipulation, mit oder ohne Übungen. Das Screening auf Gefäßrisiken beschreiben aber nur 2 der 19 vollständig. Dafür bleibt der IFOMPT-Rahmen die Grundlage."]}]}, {"t": "7. Für den Praxisalltag", "b": [{"l": ["Im ersten Termin erklären: meist harmlos, den Kopf normal weiter bewegen, keine Halskrause.", "Heimprogramm mit Kraft für Nacken und Schulter planen, zum Beispiel Rudern, Shrugs und Außenrotation, 3 × 10–15. Wer wenig Zeit hat, macht kurze Einheiten.", "Kraniozervikale Flexion, 10 × 10 s halten. Diese Dosierung ist Expertenmeinung.", "Die Übungsform nehmen, die der Patient auch durchhält. Yoga oder Pilates sind eine echte Alternative.", "Am Arbeitsplatz: Bildschirmhöhe, Pausen, Positionswechsel. Keine „richtige“ Haltung erzwingen.", "NDI am Anfang und nach 4–6 Wochen erheben, Ziel mindestens 7,5 Punkte besser.", "Vor Mobilisation oder Manipulation der HWS Gefäßzeichen und Risikofaktoren abfragen und dokumentieren."], "merk": "Fürs Patientengespräch: „Nackenschmerzen sind meist harmlos. Bewegen Sie den Kopf normal weiter. Am besten hilft regelmäßiges Krafttraining, schon kurze Einheiten zählen.“"}]}], "quellen": ["DEGAM S3 Nicht-spezifische Nackenschmerzen, AWMF 053-007, Version 3.0, 2025, gültig bis 17.02.2030", "Blanpied PR et al. Neck Pain: Clinical Practice Guidelines Revision 2017. JOSPT 2017", "Gross A et al. Exercise therapy for mechanical neck disorders. Cochrane 2015", "Andersen CH et al. Br J Sports Med 2012 (Häufigkeit und Dauer des Krafttrainings)", "de Zoete RMJ et al. Br J Sports Med 2021 (Netzwerk-Metaanalyse Übungsformen)", "Rasmussen-Barr E et al. BMC Musculoskelet Disord 2023 (Übersicht über 25 Reviews)", "Peters R et al. Phys Ther 2025 (Leitlinienvergleich Mobilisation und Gefäß-Screening)", "Rushton A et al. IFOMPT International Framework Cervical Spine. JOSPT 2023", "Hush JM et al. 2011 (Prognose); Cook C et al. 2010 (Myelopathie-Cluster); Domenech 2011 (Normwerte tiefe Halsbeuger)", "de Campos TF et al. 2018 (Vorbeugung); Sherman KJ et al. 2014 (Massage); Jull G et al. Spine 2002 (zervikogener Kopfschmerz)", "RKI BURDEN 2020; GBD 2021"], "fragen": [["Ab wann gilt Nackenschmerz laut DEGAM als chronisch?", ["Nach 4 Wochen", "Nach 6 Wochen", "Nach 6 Monaten", "Nach mehr als 12 Wochen"], 3, "DEGAM teilt ein in akut 0–3, subakut 4–12 und chronisch über 12 Wochen. Die JOSPT-Leitlinie nennt alles unter 6 Wochen akut."], ["Welche Maßnahme hat in der DEGAM-Leitlinie den Empfehlungsgrad A?", ["Traktion", "Bewegungstherapie bei chronischem Nackenschmerz", "Massage", "Kinesiotape"], 1, "Körperliche Aktivität und Bewegungstherapie bekommen Grad A. Traktion und Kinesiotape werden nicht empfohlen, Massage nur eingeschränkt."], ["Was zeigte Andersen 2012 zur Aufteilung von 1 Stunde Nacken-Schulter-Training pro Woche?", ["Ob am Stück oder aufgeteilt, machte keinen Unterschied", "Nur am Stück wirkt es", "Viele kurze Einheiten sind schlechter", "Aufgeteilt wirkt es nur bei Männern"], 0, "Ob 1 × 60, 3 × 20 oder 9 × 7 Minuten, der Schmerz sank gleich stark. Wichtig ist die Gesamtdosis."], ["Welche Übungsform ist bei chronischem Nackenschmerz laut den Übersichtsarbeiten am besten?", ["Nur Krafttraining", "Keine ist klar überlegen", "Nur Motorkontrolle der tiefen Halsbeuger", "Nur Yoga"], 1, "de Zoete 2021 und Rasmussen-Barr 2023 finden keine klar überlegene Form. Entscheidend ist, dass regelmäßig trainiert wird."], ["Ab wann gilt der Flexions-Rotations-Test als positiv?", ["Unter 60° Rotation", "Nur bei Schmerz, unabhängig vom Winkel", "Unter 32° oder mehr als 10° unter dem Normalwert", "Über 44° Rotation"], 2, "Normal sind etwa 44° je Seite. Unter 32° oder eine Abweichung über 10° spricht für eine Störung in C1/C2, typisch beim zervikogenen Kopfschmerz."], ["Ab wie vielen positiven Zeichen im Cook-Cluster ist eine Myelopathie sehr wahrscheinlich?", ["Ab 1", "Ab 3", "Ab 2", "Erst bei allen 5"], 1, "Ab 3 von 5 Zeichen ist die Myelopathie sehr wahrscheinlich (LR+ 30,9). Höchstens 1 positives Zeichen macht sie unwahrscheinlich (LR− 0,18)."], ["Welches Zeichen spricht bei Nackenschmerz für eine Gefäßursache?", ["Schmerz beim langen Sitzen", "Verspannter Trapezius", "Schmerz bei Rotation nach links", "Doppelbilder"], 3, "Doppelbilder, Schwindel, Sprach- oder Schluckstörung, Fallattacken, Nystagmus und neuer heftiger Kopf- oder Nackenschmerz sind Gefäßzeichen. Dann sofort ärztlich."], ["Welche Änderung im NDI gilt als spürbar?", ["Etwa 2 von 50 Punkten", "Etwa 20 von 50 Punkten", "Etwa 7,5 von 50 Punkten", "Erst eine Halbierung"], 2, "Je nach Studie liegt die Schwelle bei 5–33 %, typisch sind etwa 7,5 von 50 Punkten oder 15 %."], ["Welcher Muskel ist mit der 7 markiert?", ["M. sternocleidomastoideus", "M. scalenus anterior", "M. longus colli", "M. levator scapulae"], 2, "Der M. longus colli liegt vorne direkt auf den Wirbelkörpern. Er ist einer der tiefen Halsbeuger und wird mit der kraniozervikalen Flexion trainiert.", "fortbildung/bilder/2026-W47/ana-hws-muskeln2.webp"], ["Wie viele haben 1–5 Jahre nach einer Episode wieder Nackenschmerz?", ["Etwa 5–10 %", "Etwa 20 %", "Etwa 50–75 %", "Fast alle"], 2, "Rückfälle sind häufig, 50–75 % haben in 1–5 Jahren erneut Beschwerden. Regelmäßiges Training senkt das Risiko."], ["Was empfiehlt die DEGAM-Leitlinie ausdrücklich nicht?", ["Wärme in Eigenanwendung", "Aufklärung", "Krafttraining", "Kinesiotape"], 3, "Traktion, Elektrotherapie, Laser und Kinesiotape werden mit Grad B nicht empfohlen. Wärme und Aufklärung haben Grad B als Empfehlung."], ["Was hilft beim zervikogenen Kopfschmerz laut Studienlage?", ["Manuelle Therapie der oberen HWS plus Training der tiefen Halsbeuger", "Halskrause für zwei Wochen", "Nur Massage der Schultermuskeln", "Traktion der HWS"], 0, "Jull 2002: Manuelle Therapie plus Training der tiefen Halsbeuger über etwa 6 Wochen, der Effekt hielt nach 12 Monaten."], ["Was senkt laut de Campos 2018 das Risiko einer neuen Nackenschmerz-Episode?", ["Übungen", "Ergonomieprogramme allein", "Ein neues Kopfkissen", "Regelmäßige Massage"], 0, "Übungen senken neue Episoden deutlich (OR 0,32). Ergonomieprogramme allein zeigten keinen Effekt."]], "info": {"myelo": {"t": "Zervikale Myelopathie", "x": ["Druck auf das Rückenmark im Halsbereich, meist durch Verschleiß.", "Typisch: unsicherer Gang, ungeschickte Hände, beidseitige Missempfindungen. Gehört ärztlich abgeklärt."], "q": "Cook 2010"}, "degam": {"t": "DEGAM S3 2025", "x": ["Leitlinie Nicht-spezifische Nackenschmerzen, AWMF 053-007, Version 3.0, gültig bis 17.02.2030.", "Grad A: Aktivität und Bewegungstherapie bei chronischem Nackenschmerz. Grad B: Aufklärung, Wärme. Nicht empfohlen (Grad B): Traktion, Elektrotherapie, Laser, Kinesiotape."], "q": "AWMF 053-007"}, "jospt": {"t": "JOSPT-Einteilung", "x": ["Nackenschmerz mit Mobilitätsdefizit, mit Koordinationsstörung, mit Kopfschmerz, mit ausstrahlendem Schmerz.", "Die Leitlinie (Revision 2017) wird gerade überarbeitet. Bis die Neufassung erscheint, gilt die Fassung von 2017."], "q": "Blanpied 2017"}, "ccsr": {"t": "Canadian C-Spine Rule", "x": ["Entscheidungsregel nach Nackentrauma, ob geröntgt werden muss.", "Sensitivität 1,00 in einer Metaanalyse 2023: Wer nach der Regel kein Bild braucht, hat praktisch keine Fraktur."], "q": "Metaanalyse 2023"}, "cook": {"t": "Cook-Cluster", "x": ["Fünf Zeichen für eine zervikale Myelopathie: Gangabweichung, Hoffmann-Zeichen, inverser Radiusreflex, Babinski, Alter über 45.", "Höchstens 1 positiv: Myelopathie unwahrscheinlich (LR− 0,18). 3 oder mehr: sehr wahrscheinlich (LR+ 30,9)."], "q": "Cook 2010"}, "ifompt": {"t": "IFOMPT-Rahmen", "x": ["Internationaler Rahmen zur Untersuchung der HWS auf Gefäßursachen vor manueller Therapie (2020, JOSPT 2023).", "Kein einzelner Test ist verlässlich. Entscheidend sind Anamnese, Risikofaktoren und das klinische Gesamtbild."], "q": "Rushton 2023"}, "frt": {"t": "Flexions-Rotations-Test", "x": ["Rückenlage, HWS passiv voll gebeugt, damit die unteren Segmente sperren. Dann Rotation zu beiden Seiten, die vor allem in C1/C2 stattfindet.", "Normal etwa 44° pro Seite. Positiv bei unter 32° oder mehr als 10° unter dem Normalwert."], "q": "Hall 2010"}, "ndi": {"t": "Neck Disability Index", "x": ["10 Fragen, 0–50 Punkte oder 0–100 %, höher ist schlechter.", "Spürbare Änderung je nach Studie 5–33 %, typisch etwa 7,5 Punkte (15 %)."], "q": "Fragebogen"}, "andersen": {"t": "Andersen 2012", "x": ["Cluster-RCT mit 447 Büroangestellten: 1 h Nacken-Schulter-Krafttraining pro Woche über 20 Wochen.", "Ob 1 × 60, 3 × 20 oder 9 × 7 Minuten, machte für den Schmerz keinen Unterschied."], "q": "Br J Sports Med 2012"}, "dezoete": {"t": "de Zoete 2021", "x": ["Netzwerk-Metaanalyse mit 40 RCTs zu Übungsformen bei chronischem Nackenschmerz.", "Motorkontrolle, Yoga, Pilates, Tai Chi, Qigong und Krafttraining wirkten etwa gleich gut, bei sehr niedriger Qualität der Evidenz."], "q": "Br J Sports Med 2021"}, "rasmussen": {"t": "Rasmussen-Barr 2023", "x": ["Übersicht über 25 systematische Reviews mit über 17.000 Teilnehmenden.", "Alle Übungsformen senkten kurzfristig den Schmerz. Bei der Beeinträchtigung zeigte Krafttraining allein keinen klaren Effekt, die anderen Formen schon. Eine beste Form lässt sich nicht benennen."], "q": "BMC Musculoskelet Disord 2023"}, "peters": {"t": "Peters 2025", "x": ["Systematischer Review von 19 Leitlinien zu Nackenschmerz, 5 davon hochwertig.", "Alle hochwertigen empfehlen Mobilisation oder Manipulation. Von allen 19 beschreiben nur 2 das Screening auf Gefäßrisiken vollständig."], "q": "Phys Ther 2025"}}}, {"id": "w48-rad", "titel": "Lumbale Radikulopathie und Bandscheibenvorfall", "art": "kb", "kb": "WS02", "min": 12, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Gewebe aus dem Nucleus pulposus tritt durch den Faserring aus und drückt auf eine lumbale Nervenwurzel, meist L5 (bei LWK4/5) oder S1 (bei LWK5/SWK1). Der Beinschmerz entsteht durch den Druck und zusätzlich durch eine chemische Reizung der Wurzel. Darum passen Bildbefund und Beschwerden oft nicht zusammen."]}, {"l": ["[[Radikulärer Schmerz und Radikulopathie|radikulaer]] sind zu trennen: Radikulärer Schmerz strahlt ins Dermatom aus, bei der Radikulopathie kommen Ausfälle dazu. Die Ausfälle bestimmen, wie dringend es ist.", "Auslöser ist oft Heben in Beugung und Rotation, auf dem Boden einer Degeneration des Faserrings.", "Vorfälle finden sich auch bei Gesunden häufig: Protrusionen bei 29 % der 20-Jährigen und 43 % der 80-Jährigen ohne Beschwerden ([[Brinjikji 2015|brinjikji]])."]}]}, {"t": "2. Wurzeln, Kennmuskeln und Verlauf", "b": [{"tab": [["L3", "Quadrizeps, Hüftbeuger, Adduktoren. PSR. Ausstrahlung bis zum Knie"], ["L4", "Quadrizeps, Hüftbeuger. PSR. Tibiavorderkante"], ["L5", "Großzehen- und Fußheber, Gluteus medius. Tibialis-posterior-Reflex. Unterschenkel außen, Fußrücken bis Großzehe"], ["S1", "Fußsenker, Gluteus maximus. ASR. Wade bis Fußaußenrand"]]}, {"bars": [["Deutlich besser in 6–12 Wochen", 70, "60–80 % ohne OP"], ["Sequester bilden sich zurück", 96, "gerade große Vorfälle am häufigsten"], ["Extrusionen bilden sich zurück", 70, ""], ["Nach 5 Jahren nicht erholt", 8, "mit und ohne OP gleich"]]}, {"p": ["In der Primärversorgung ist nach 12 Monaten nur gut die Hälfte gebessert, ein Teil behält wechselnde Beschwerden (ATLAS, Konstantinou 2018). Am stärksten ungünstig sind eine lange Dauer des Beinschmerzes und die Überzeugung, dass es lange dauern wird. Der MRT-Befund sagt den Verlauf kaum voraus."], "merk": "Gerade große Vorfälle bilden sich am häufigsten zurück. Das ist eine gute Nachricht für den Patienten."}]}, {"t": "3. Red Flags zuerst", "b": [{"tab": [["Cauda-equina-Zeichen", "Neue Probleme beim Wasserlassen, Taubheit im Gesäß- oder Genitalbereich, Verlust des Rektumgefühls, sexuelle Störung, Ausfälle an beiden Beinen. Sofort Notaufnahme"], ["Schwere Parese", "Kraftgrad 3/5 oder schlechter oder zunehmend. Am selben Tag ärztlich"], ["Schmerz lässt nach, Parese bleibt", "Kann auf einen Wurzeltod hinweisen. Ärztlich"], ["Plötzlich beidseitiger Beinschmerz", "Dringlich ärztlich"], ["Sonstige Warnzeichen", "Tumoranamnese, Fieber, Gewichtsverlust, Trauma bei Osteoporose, Nachtschmerz"]]}, {"p": ["Das [[Cauda-equina-Syndrom|ces]] ist selten, 1–3 je 100.000 Menschen pro Jahr. Die klassischen Zeichen sind wenig sensitiv (19–43 %), ihr Fehlen schließt es nicht aus. Der britische Versorgungspfad von 2023 verlangt bei neuen Symptomen die sofortige Notaufnahme und ein MRT innerhalb von 4 Stunden."], "merk": "Blase und Darm bei jedem Ischias-Patienten aktiv erfragen, auch wenn er es nicht selbst anspricht."}]}, {"t": "4. Befund und Abgrenzung", "b": [{"l": ["Anamnese: Rücken- und Beinschmerz getrennt erfassen, Blase und Darm, psychosoziale Faktoren.", "Kennmuskeln im Seitenvergleich. Eine leichte Fußsenkerschwäche fällt erst beim einbeinigen Zehenstand auf, eine leichte Quadrizepsschwäche beim Stufensteigen. Gluteen mitprüfen.", "Reflexe und Sensibilität ergänzen, sie sind weniger ergiebig als die Motorik.", "Lasègue, gekreuzter Lasègue, Slump. Bei hohen Wurzeln den Femoralis-Dehnungstest."]}, {"p": ["Der Lasègue ist sehr sensitiv (92 %), aber kaum spezifisch (28 %). Ein negativer Test macht einen relevanten Vorfall unwahrscheinlicher. Der gekreuzte Lasègue ist umgekehrt spezifisch (90 %) und bestätigt eher ([[Cochrane 2010|windt]]). Die Daten stammen fast nur aus chirurgischen Patientengruppen, mehrere Befunde zusammen sagen mehr als einer allein."]}, {"tab": [["Nicht-spezifischer Kreuzschmerz", "Ausstrahlung höchstens bis zum Knie, Neurologie unauffällig"], ["Spinalkanalstenose", "älter, Beschwerden beim Gehen, besser beim Vorbeugen"], ["Pseudoradikulär (Hüfte, ISG, Facetten)", "Neurologie unauffällig, Schmerz nicht im Dermatom"], ["Polyneuropathie", "beidseits, strumpfförmig, langsamer Beginn"], ["Entzündung, Zoster, Borrelien, Tumor", "Nachtschmerz, bewegungsunabhängig, ohne Nervendehnungszeichen. Ärztlich"]]}, {"l": ["Messen: NRS für Bein und Rücken getrennt (spürbar 2 Punkte oder 30 %), ODI 10 Punkte, RMDQ 5 Punkte ([[Ostelo 2008|ostelo]]).", "Kraftgrade bei jedem Termin kurz prüfen und dokumentieren."]}]}, {"t": "5. Bildgebung", "b": [{"p": ["Ohne Warnzeichen anfangs kein MRT. Es kommt erst, wenn es nach 6–8 Wochen nicht besser wird oder eine OP in Frage steht."], "fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-prolaps.webp", "t": "Posterolateraler Bandscheibenvorfall, Blick von oben.", "c": "1 Vorfall des Nucleus durch den Faserring, 2 bedrängte Nervenwurzel, 3 Duralsack mit Cauda equina, 4 Facettengelenk. Vorne liegt im Bild unten."}], "merk": "Das hintere Längsband deckt in der LWS nur die Mitte ab, Vorfälle gehen deshalb meist posterolateral. Ein Vorfall L4/5 trifft dann die Wurzel L5, ein Vorfall L5/S1 die Wurzel S1."}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "6. Was hilft laut Studienlage?", "b": [{"p": ["Die deutschen Leitlinien sind abgelaufen: die DGN-Leitlinie 030-058 seit Januar 2023, die [[S2k 187-057|s2k]] seit Juli 2025, sie ist in Überarbeitung. NICE NG59 ist evidenzbasiert und wurde am 29.07.2026 zuletzt geändert. Alle setzen auf Aufklärung, aktiv bleiben und aktive Physiotherapie."]}, {"l": ["Akut: aktiv bleiben, Bettruhe höchstens kurz (nicht über 4 Tage). Richtungspräferenz testen, zum Beispiel wiederholte Extension in Bauchlage, wenn der Beinschmerz zentralisiert.", "Frühe Physiotherapie über 4 Wochen (Übungen plus manuelle Therapie) senkte den ODI nach 6 Monaten um 5 Punkte, ein kleiner, aber messbarer Effekt (Fritz 2021).", "Übungen statt nur „aktiv bleiben“ bringen nur kurzfristig einen kleinen Vorteil beim Beinschmerz. McKenzie und Neurodynamik sind nicht besser belegt als gute aktive Therapie.", "OP oder konservativ: Eine frühe OP lindert schneller, nach 1, 2 und 5 Jahren gibt es keinen Unterschied ([[Peul 2007|peul]]). Bei Ischias seit 4–12 Monaten war die OP besser als weitere konservative Behandlung (Beinschmerz 2,8 gegen 5,2 nach 6 Monaten, Bailey 2020).", "Pregabalin und Gabapentin wirken bei Ischias nicht besser als Placebo (PRECISE, Mathieson 2017). NICE rät ab.", "Epidurale Kortisoninjektion: kurzfristig etwa 5 von 100 Punkten weniger Beinschmerz (Cochrane 2020). Das ist eine ärztliche Entscheidung.", "Nach Mikrodiskektomie: Übungsprogramm ab Woche 4–6, eher intensiv, betreut oder zu Hause gleich gut (Cochrane, Oosterhuis 2014). Pauschale Sitz- oder Hebeverbote sind nicht nötig."]}, {"tab": [["Nicht empfohlen", "Bettruhe über 4 Tage, Manipulation im betroffenen Segment, Traktion in der Akutphase"], ["Akut nicht", "Elektrotherapie, Massage, Akupunktur (S2k 187-057)"], ["Bei NICE nicht", "TENS, Ultraschall, Interferenzstrom, Korsetts"]], "merk": "Die meisten werden ohne OP besser. Eine OP macht es schneller, aber nach einem Jahr nicht besser."}]}, {"t": "7. Was neu ist", "b": [{"l": ["[[Zhu 2025|zhu]]: Zwei Netzwerk-Metaanalysen zur nicht-operativen Behandlung, akut und subakut (40 RCTs) und chronisch (50 RCTs). Die Evidenz hatte durchgehend sehr niedriges Vertrauen, keine Maßnahme ist klar besser belegt als eine andere.", "Dove 2023 kam mit 18 RCTs zum selben Bild: Physiotherapie gegen Kontrollen insgesamt ohne klaren Unterschied, gegen reine Beratung langfristig etwas weniger Schmerz.", "NICE hat NG59 am 29.07.2026 geändert und zwei Empfehlungen zu psychologischer Therapie und kombinierten Programmen gestrichen.", "Seit Juni 2025 gibt es die deutsche [[S3-Leitlinie Epidurale Injektionen|s3epi]] (AWMF 151-005, gültig bis 22.06.2030)."], "merk": "Die Studienlage ist dünn. Umso wichtiger sind gute Aufklärung, Aktivität und das Beobachten der Neurologie."}]}, {"t": "8. Für den Praxisalltag", "b": [{"l": ["Bei jedem Termin Kraftgrade der Kennmuskeln kurz prüfen, zum Beispiel einbeiniger Zehenstand und Großzehenheber.", "Blase, Darm und Reithosengefühl erfragen und dokumentieren.", "Neurodynamik als Gleiten (Slider) statt Spannen, 2–3 × 10, schmerzfrei.", "Gehen in kurzen Einheiten mehrmals täglich, langsam steigern.", "Belastung erst steigern, wenn der Beinschmerz zentralisiert oder abnimmt.", "Keine Besserung nach 6–12 Wochen: die OP-Frage ärztlich klären lassen.", "Nach Mikrodiskektomie Klinikvorgaben beachten, manuelle Therapie im operierten Segment mindestens 6 Wochen meiden (Expertenmeinung)."], "merk": "Fürs Patientengespräch: „Gerade große Vorfälle bilden sich am häufigsten zurück. Die meisten werden ohne OP besser. Wichtig ist, dass wir Ihre Kraft im Bein im Blick behalten.“"}]}], "quellen": ["DGOOC/DGOU S2k Bandscheibenvorfälle mit radikulärer Symptomatik, AWMF 187-057 (früher 033-048), gültig bis 30.07.2025, in Überarbeitung", "DGN S2k Lumbale Radikulopathie, AWMF 030-058, abgelaufen 10.01.2023", "NICE NG59 Low back pain and sciatica, 2016, Medikamente 2020, Änderung 29.07.2026", "GIRFT National Suspected Cauda Equina Syndrome Pathway 2023", "van der Windt DA et al. Cochrane 2010 (klinische Untersuchung)", "Peul WC et al. N Engl J Med 2007; Bailey CS et al. N Engl J Med 2020", "Fritz JM et al. Ann Intern Med 2021; Mathieson S et al. N Engl J Med 2017 (PRECISE)", "Oosterhuis T et al. Cochrane 2014 (Reha nach Bandscheiben-OP); Cochrane 2020 (epidurale Steroide)", "Konstantinou K et al. 2018 (ATLAS); Brinjikji W et al. AJNR 2015; Ostelo RW et al. Spine 2008", "Zhu Z et al. JOSPT 2025 und J Pain 2025 (Netzwerk-Metaanalysen); Dove L et al. Eur Spine J 2023", "S3 Epidurale Injektionen bei degenerativen Erkrankungen, AWMF 151-005, 2025, gültig bis 22.06.2030"], "fragen": [["Welche Wurzel wird bei einem posterolateralen Vorfall in Höhe L4/5 meist bedrängt (Ziffer 2)?", ["L4", "S1", "L5", "L3"], 2, "Der posterolaterale Vorfall trifft die Wurzel, die eine Etage tiefer austritt. Bei L4/5 ist das meist L5, bei L5/S1 meist S1.", "fortbildung/bilder/2026-W47/ana-lws-prolaps.webp"], ["Welcher Test deckt eine leichte Schwäche der Wurzel S1 am besten auf?", ["Fersengang", "Einbeiniger Zehenstand mehrmals hintereinander", "Großzehe gegen Widerstand heben", "Stufensteigen"], 1, "S1 versorgt die Fußsenker. Eine leichte Schwäche fällt erst bei wiederholtem einbeinigem Zehenstand auf."], ["Welcher Test ist bei Bandscheibenvorfall eher spezifisch?", ["Lasègue", "Gekreuzter Lasègue", "Slump-Test", "Femoralis-Dehnungstest"], 1, "Der gekreuzte Lasègue hat eine Spezifität von etwa 90 %, ist aber wenig sensitiv. Der normale Lasègue ist sensitiv (92 %), aber kaum spezifisch."], ["Was stimmt beim Verdacht auf ein Cauda-equina-Syndrom?", ["Erst abwarten, ob es sich in 2 Tagen bessert", "Fehlen die klassischen Zeichen, ist es ausgeschlossen", "Sofort in die Notaufnahme, MRT innerhalb von 4 Stunden", "Erst ein Röntgen beim Hausarzt"], 2, "Der britische Pfad 2023 verlangt die sofortige Notaufnahme. Die klassischen Zeichen sind wenig sensitiv, ihr Fehlen schließt nichts aus."], ["Ein Patient hat eine Fußheberschwäche Kraftgrad 3/5. Was ist richtig?", ["Weiter Physiotherapie, in 4 Wochen neu prüfen", "Erst nach 6 Wochen ein MRT", "Nur Kräftigung, das reicht", "Am selben Tag ärztlich vorstellen"], 3, "Eine Parese mit Kraftgrad 3/5 oder schlechter oder eine zunehmende Parese gehört am selben Tag ärztlich abgeklärt."], ["Was zeigte Peul 2007 beim Vergleich frühe OP gegen konservativ?", ["OP ist nach einem Jahr deutlich besser", "OP lindert schneller, nach einem Jahr kein Unterschied", "Konservativ ist in allem besser", "Nach OP gibt es mehr Rückfälle"], 1, "Nach OP sank der Schmerz schneller. Nach einem Jahr waren in beiden Gruppen etwa 95 % erholt."], ["Wie oft bilden sich Sequester zurück?", ["In etwa 96 %", "Fast nie", "Etwa in einem Drittel", "Etwa in der Hälfte"], 0, "Gerade große, sequestrierte Vorfälle bilden sich am häufigsten zurück, in etwa 96 %. Extrusionen in etwa 70 %."], ["Was zeigte die PRECISE-Studie zu Pregabalin bei Ischias?", ["Nicht besser als Placebo", "Deutlich weniger Beinschmerz", "Nur in Kombination mit Kortison wirksam", "Besser als Physiotherapie"], 0, "Pregabalin war bei Ischias nicht besser als Placebo, hatte aber mehr Nebenwirkungen. NICE rät von Pregabalin und Gabapentin ab."], ["Wann ist bei Ischias ohne Warnzeichen ein MRT sinnvoll?", ["Sofort beim ersten Termin", "Nie", "Nur bei Rückenschmerz ohne Beinschmerz", "Erst wenn es nach 6–8 Wochen nicht besser wird"], 3, "Ohne Warnzeichen anfangs kein MRT. Es kommt, wenn es nach 6–8 Wochen nicht besser wird oder eine OP in Frage steht."], ["Welche Änderung im ODI gilt als spürbar?", ["2 Punkte", "5 Punkte", "10 Punkte", "30 Punkte"], 2, "Nach Ostelo 2008 gelten 10 Punkte im ODI als spürbar, 5 Punkte im RMDQ, 2 Punkte oder 30 % auf der NRS."], ["Wie soll Neurodynamik bei akuter Radikulopathie dosiert werden?", ["Maximal spannen, bis der Schmerz einschießt", "Gar nicht, Nerven nie bewegen", "Nur passiv durch den Therapeuten", "Als Gleiten (Slider), schmerzfrei"], 3, "Gleiten statt Spannen, 2–3 × 10 Wiederholungen ohne Schmerzverstärkung."], ["Ab wann beginnt nach Mikrodiskektomie meist das strukturierte Übungsprogramm?", ["Ab Woche 4–6", "Ab dem OP-Tag mit Krafttraining", "Erst nach 6 Monaten", "Gar nicht, Schonung reicht"], 0, "Gehen und Mobilisieren gleich nach der OP, das strukturierte Übungsprogramm ab Woche 4–6. Übungen führten nicht zu mehr Reoperationen."], ["Was fanden die Netzwerk-Metaanalysen von Zhu 2025 zur nicht-operativen Behandlung bei Ischias?", ["Manuelle Therapie ist klar am besten", "Nur Medikamente helfen", "Die Evidenz ist sehr unsicher, keine Maßnahme ist klar überlegen", "Bettruhe ist am wirksamsten"], 2, "Einzelne Maßnahmen zeigten kurzfristig Effekte, aber alle Ergebnisse hatten sehr niedriges Vertrauen."]], "info": {"radikulaer": {"t": "Radikulärer Schmerz und Radikulopathie", "x": ["Radikulärer Schmerz: ausstrahlender Schmerz im Dermatom ohne neurologisches Defizit.", "Radikulopathie: mit Ausfällen bei Kraft, Reflex oder Sensibilität. Die Ausfälle bestimmen, wie dringend ärztlich abgeklärt wird."], "q": "S2k 187-057"}, "brinjikji": {"t": "Brinjikji 2015", "x": ["Metaanalyse mit 3110 Menschen ohne Rückenschmerzen.", "Protrusionen bei 29 % der 20-Jährigen und 43 % der 80-Jährigen, Bandscheibendegeneration bei 37–96 %."], "q": "AJNR 2015"}, "ces": {"t": "Cauda-equina-Syndrom", "x": ["Kompression mehrerer Wurzeln der Cauda equina, 1–3 je 100.000 Menschen pro Jahr.", "Klassische Zeichen sind wenig sensitiv (19–43 %). Britischer Pfad 2023: bei neuen Symptomen sofort Notaufnahme, MRT binnen 4 Stunden."], "q": "GIRFT 2023"}, "windt": {"t": "Cochrane 2010 (van der Windt)", "x": ["Übersicht zur Genauigkeit der klinischen Untersuchung bei Bandscheibenvorfall.", "Lasègue: Sensitivität 0,92, Spezifität 0,28. Gekreuzter Lasègue: Sensitivität 0,28, Spezifität 0,90."], "q": "Cochrane 2010"}, "ostelo": {"t": "Ostelo 2008", "x": ["Internationaler Konsens zu spürbaren Änderungen bei Rückenschmerz.", "NRS 2 Punkte, RMDQ 5, ODI 10, oder 30 % besser als am Anfang."], "q": "Spine 2008"}, "s2k": {"t": "S2k 187-057", "x": ["Leitlinie der DGOOC zur konservativen, operativen und rehabilitativen Versorgung bei Bandscheibenvorfällen mit radikulärer Symptomatik (früher 033-048).", "Konsens ohne systematische Evidenzbewertung, gültig bis 30.07.2025, in Überarbeitung."], "q": "AWMF 187-057"}, "peul": {"t": "Peul 2007", "x": ["RCT mit 283 Patienten mit schwerer Ischias seit 6–12 Wochen: frühe OP gegen verlängert konservativ.", "Nach OP schnellere Schmerzlinderung, nach 1 Jahr in beiden Gruppen 95 % erholt. 39 % der konservativ Behandelten wurden später operiert."], "q": "N Engl J Med 2007"}, "zhu": {"t": "Zhu 2025", "x": ["Zwei Netzwerk-Metaanalysen: akut und subakut 40 RCTs mit 5381 Teilnehmenden (JOSPT), chronisch 50 RCTs mit 4920 Teilnehmenden (J Pain).", "Die gesamte Evidenz hatte sehr niedriges Vertrauen. Keine nicht-operative Behandlung ist klar besser belegt als eine andere."], "q": "JOSPT 2025; J Pain 2025"}, "s3epi": {"t": "S3 Epidurale Injektionen", "x": ["S3-Leitlinie Epidurale Injektionen bei degenerativen Erkrankungen, AWMF 151-005, federführend die Deutsche Wirbelsäulengesellschaft.", "Version 1.0 vom 23.06.2025, gültig bis 22.06.2030. Die Injektion ist eine ärztliche Entscheidung."], "q": "AWMF-Register 151-005"}}}, {"id": "w48-rm", "titel": "Rotatorenmanschetten-Tendinopathie", "art": "kb", "kb": "SH01", "min": 11, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Die Sehnen der Rotatorenmanschette sind mehr belastet, als sie gerade vertragen, und reagieren mit einer [[Tendinopathie|tendinopathie]]. Der Schleimbeutel unter dem Schulterdach kann mitgereizt sein. Früher hieß das Impingement. Die Enge unter dem Akromion erklärt die Beschwerden aber schlechter als lange gedacht."]}, {"l": ["Die US-Leitlinie [[JOSPT 2025|jospt]] fasst subakromiales Schmerzsyndrom, Impingement, Bursitis, Tendinopathie der langen Bizepssehne und Partialrupturen zusammen. Komplette Rupturen und die Schultersteife gehören nicht dazu.", "Die deutsche [[S2e-Leitlinie|s2e]] spricht noch von subakromialem Impingement. Sie galt bis 19.11.2026, eine Überarbeitung ist offen.", "16–21 % haben gerade oder im letzten Jahr Schulterschmerz, mehr als die Hälfte davon geht auf die Rotatorenmanschette. Etwa 38 neue Fälle je 1000 Personen pro Jahr.", "Typisch sind Überkopfarbeit, Wurf- und Schwimmsport und eine schnelle Laststeigerung. Frauen sind etwas häufiger betroffen.", "34 % der Beschwerdefreien haben einen Sehnenbefund im Ultraschall. Der Befund allein erklärt den Schmerz also nicht."]}]}, {"t": "2. Typische Symptome und Verlauf", "b": [{"l": ["Schmerz seitlich am Oberarm, oft bis zum Ansatz des M. deltoideus", "Schmerzhafter Bogen beim seitlichen Heben, etwa zwischen 60° und 120°", "Nachtschmerz beim Liegen auf der betroffenen Seite", "Schmerz bei Widerstand gegen Abduktion und Außenrotation, die Kraft ist eher erhalten", "Passiv weitgehend frei beweglich, anders als bei der Frozen Shoulder"]}, {"bars": [["Nach 1 Monat erholt", 23, "Schulterschmerz allgemein in der Hausarztpraxis"], ["Nach 1 Jahr erholt", 59, "41 % haben noch Beschwerden"]]}, {"p": ["Die meisten sind nach etwa 3 Monaten deutlich besser. Die Zahlen oben stammen aus [[van der Windt 1996|windt]] und gelten für Schulterschmerz allgemein. Ungünstig sind Alter über 55, hohe Arbeitsbelastung, starker Schmerz zu Beginn, gleichzeitiger Nackenschmerz und eine lange Dauer."], "merk": "Die Sehne ist überlastet, nicht kaputt. Sie wird wieder belastbar, wenn die Last Schritt für Schritt steigt."}]}, {"t": "3. Befund und Abgrenzung", "b": [{"l": ["HWS screenen und Warnzeichen abfragen.", "Aktiv gegen passiv: Passiv weitgehend frei spricht gegen eine Frozen Shoulder.", "Kraft der Außenrotation und Abduktion mit dem Handdynamometer messen, nicht nach Gefühl. Erst Unterschiede über 15–20 % sind sicher mehr als Messfehler.", "Provokationstests immer im Cluster deuten, nie einzeln."]}, {"tab": [["Painful Arc", "LR+ 3,4, LR− 0,46: bestätigt eher"], ["Hawkins-Kennedy", "LR+ 2,7, LR− 0,25: negativ schließt eher aus"], ["Neer", "LR+ 1,5, LR− 0,68: wenig Nutzen"], ["3 von 5 Tests positiv", "LR+ 2,9, LR− 0,34 (Hawkins, Neer, Painful Arc, Jobe, Außenrotation gegen Widerstand)"]]}, {"tab": [["Komplette Ruptur", "Trauma, deutliche Schwäche, Arm fällt. Lag Signs, Drop Arm, Ultraschall"], ["Frozen Shoulder", "passiv ebenso eingeschränkt, Außenrotation am stärksten"], ["Kalkschulter", "plötzlicher, sehr starker Schmerz. Röntgen zeigt das Depot"], ["ACG-Arthrose", "Schmerz oben auf der Schulter, Arm quer vor dem Körper"], ["Instabilität", "jünger, Überkopfsport, Gefühl des Wegrutschens"], ["Zervikale Radikulopathie", "Ausstrahlung unter den Ellenbogen, Kribbeln"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-subakromial.webp", "t": "Subakromialer Raum, rechte Schulter von vorne-lateral.", "c": "1 Akromion, 2 Lig. coracoacromiale, 3 Bursa subacromialis, 4 Supraspinatussehne, 5 Tuberculum majus."}], "merk": "Bildgebung erst, wenn es nach höchstens 12 Wochen nicht besser wird, früher nur bei Trauma oder Verdacht auf komplette Ruptur. Ultraschall vor MRT."}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."]}]}, {"t": "4. Reizbarkeit und Messen", "b": [{"p": ["Ein geprüftes Stufenmodell gibt es für die Rotatorenmanschette nicht. [[STAR-Shoulder|star]] schlägt drei Stufen vor. Die Tabelle ist eine Orientierung, Expertenmeinung."]}, {"tab": [["Hoch", "NAS 7 oder mehr, regelmäßig Nachtschmerz, schon leichte Last provoziert lange"], ["Mittel", "NAS 4–6, zeitweise nachts, Schmerz bei Last klingt bis zum nächsten Tag ab"], ["Niedrig", "NAS 3 oder weniger, kaum nachts, nur hohe oder Überkopflast stört"]]}, {"l": ["[[SPADI|spadi]] oder QuickDASH zu Beginn und alle 4 Wochen. Spürbar besser ab etwa 8–13 Punkten im SPADI.", "Kraft Außenrotation und Abduktion in kg im Seitenvergleich.", "Schmerz bei der schwierigsten Alltagsbewegung auf der NAS."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"p": ["Aktive Übungen sind die Erstbehandlung (JOSPT Grad A, S2e „soll“). Entscheidend ist, dass die Last steigt. [[Progressives Krafttraining|progressiv]] senkte den Schmerz um gut einen Punkt auf der 10er-Skala, Übungen ohne Steigerung brachten nichts."]}, {"l": ["[[Holmgren 2012|holmgren]]: 102 Patienten auf der OP-Warteliste. Nach 12 Wochen exzentrischer Übungen für Rotatorenmanschette und Schulterblatt wollten nur noch 20 % operiert werden, in der Kontrollgruppe 63 %.", "Schwer oder leicht trainieren macht kaum einen Unterschied ([[Ingwersen 2017|ingwersen]]). Unter Anleitung ist nicht besser als zu Hause.", "Hohe Reizbarkeit: Isometrie für Außenrotation und Abduktion, 5 × 30–45 s (Expertenmeinung), Last anpassen statt Ruhe, ärztlich eine Injektion besprechen.", "Mittlere Reizbarkeit: exzentrisch Supraspinatus und Außenrotatoren 3 × 15, Schulterblattmuskeln, Last etwa alle 2 Wochen steigern.", "Niedrige Reizbarkeit: schwerer und über Schulterhöhe trainieren, 3 × 8–12, dann arbeits- oder sportspezifisch.", "Manuelle Therapie bringt einen kleinen, kurzfristigen Zusatzeffekt.", "Kortisoninjektion hilft etwa 4–8 Wochen, etwa jeder Fünfte profitiert, danach kein Unterschied mehr."]}, {"tab": [["Nicht empfohlen", "therapeutischer Ultraschall, Stoßwelle ohne Kalk, PRP, Hyaluronsäure"], ["Operation", "[[Subakromiale Dekompression|sad]] war nicht besser als eine Schein-OP oder Training"]], "merk": "Schmerzregel nach Holmgren: bis 5 von 10 während der Übung erlaubt, bis zur nächsten Einheit wieder auf dem Ausgangsniveau."}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Erst die Reizbarkeit einstufen, dann die Intensität danach wählen.", "Heimprogramm über 12 Wochen planen, 1–2× täglich, Kontrolle alle 1–2 Wochen.", "Last alle etwa 2 Wochen steigern, sobald die Wiederholungen sauber gehen.", "Nach 6–8 Wochen ohne Fortschritt eine Injektion ärztlich besprechen, nach höchstens 12 Wochen ohne Besserung Bildgebung und fachärztliche Abklärung.", "Eine OP frühestens nach 6 Monaten konservativer Therapie (BESS). Die S2e empfiehlt sie dann noch, die Placebo-Studien sprechen dagegen."], "merk": "Fürs Patientengespräch: „Die Sehne ist überlastet, nicht kaputt. Sie wird wieder belastbar, wenn wir sie Schritt für Schritt mehr fordern. Das dauert meist etwa drei Monate.“"}]}], "quellen": ["Desmeules F et al. Rotator cuff tendinopathy: clinical practice guideline. JOSPT 2025", "DGOU/DVSE S2e Subakromiales Impingement, AWMF 187-060, 2021, gültig bis 19.11.2026", "BESS Patient Care Pathway Subacromial Pain 2025; BMJ Rapid Recommendation 2019", "Holmgren T et al. BMJ 2012; Ingwersen KG et al. 2017", "van der Windt DA et al. 1996; McClure PW, Michener LA. Phys Ther 2015 (STAR-Shoulder)"], "fragen": [["Wo liegt der schmerzhafte Bogen bei der Rotatorenmanschetten-Tendinopathie typischerweise?", ["0–30° Abduktion", "Nur über 160°", "Etwa 60–120° Abduktion", "Nur in Außenrotation"], 2, "Der Painful Arc liegt etwa zwischen 60° und 120°. Schmerz erst endgradig spricht eher für das AC-Gelenk."], ["Welcher Befund spricht gegen eine Frozen Shoulder und für die Tendinopathie?", ["Passiv weitgehend frei beweglich", "Passive Außenrotation stark eingeschränkt", "Nachtschmerz", "Schmerz seitlich am Oberarm"], 0, "Bei der Tendinopathie ist die passive Beweglichkeit weitgehend frei. Bei der Frozen Shoulder ist sie passiv genauso eingeschränkt, die Außenrotation am stärksten."], ["Welcher Test hilft vor allem beim Ausschließen, wenn er negativ ist?", ["Neer", "Painful Arc", "Drop Arm", "Hawkins-Kennedy"], 3, "Hawkins-Kennedy hat ein LR− von 0,25. Ist er negativ, wird die Diagnose unwahrscheinlicher."], ["Was zeigte Holmgren 2012 bei Patienten auf der OP-Warteliste?", ["Alle wollten nach dem Training noch operiert werden", "Training verschlechterte den Schmerz", "Nach Training wollten nur 20 % statt 63 % operiert werden", "Nur die Injektion wirkte"], 2, "Nach 12 Wochen exzentrischer Übungen für Rotatorenmanschette und Schulterblatt entschieden sich nur 20 % für eine OP, in der Kontrollgruppe 63 %."], ["Was ist beim Training der Rotatorenmanschette laut Studienlage entscheidend?", ["Dass die Last steigt", "Dass möglichst schwer trainiert wird", "Dass immer ein Therapeut dabei ist", "Dass nur isometrisch trainiert wird"], 0, "Progressive Last wirkt, Übungen ohne Steigerung brachten nichts. Schwer gegen leicht und betreut gegen zu Hause machten kaum einen Unterschied."], ["Wie lange hilft eine subakromiale Kortisoninjektion etwa?", ["Einen Tag", "Mindestens ein Jahr", "Dauerhaft", "Etwa 4–8 Wochen"], 3, "Sie hilft etwa 4–8 Wochen, etwa jeder Fünfte profitiert. Danach ist kein Unterschied mehr da, wiederholte Spritzen sind nicht besser."], ["Was ist mit der 3 markiert?", ["Supraspinatussehne", "Lig. coracoacromiale", "Akromion", "Bursa subacromialis"], 3, "Die 3 ist die Bursa subacromialis zwischen Schulterdach und Supraspinatussehne. Sie kann bei der Tendinopathie mitgereizt sein.", "fortbildung/bilder/2026-W47/ana-sch-subakromial.webp"], ["Was zeigten die Placebo-Studien zur subakromialen Dekompression?", ["Deutlich besser als Training", "Nicht besser als Schein-OP oder Training", "Nur bei Frauen wirksam", "Besser als Schein-OP, schlechter als Training"], 1, "In CSAW und FIMPACT war die Dekompression nach einem Jahr nicht besser als eine Schein-OP. Die BMJ-Empfehlung 2019 rät stark ab."], ["Wie lautet die Schmerzregel aus Holmgren 2012?", ["Übungen nur völlig schmerzfrei", "Bis 5 von 10 erlaubt, bis zur nächsten Einheit zurück auf das Ausgangsniveau", "Bis 8 von 10 erlaubt, solange es am Abend besser ist", "Schmerz spielt keine Rolle"], 1, "Bis 5 von 10 während der Übung, bis zur nächsten Einheit wieder auf dem Ausgangsniveau. Sonst Last reduzieren."], ["Wann ist Bildgebung bei Verdacht auf Rotatorenmanschetten-Tendinopathie sinnvoll?", ["Immer beim ersten Termin", "Nie", "Nach höchstens 12 Wochen ohne Besserung oder nach Trauma", "Nur ein MRT vor jedem Training"], 2, "Zu Beginn keine Bildgebung. Ultraschall erst nach höchstens 12 Wochen ohne Besserung, früher bei Trauma oder Verdacht auf komplette Ruptur."], ["Ab wie vielen Punkten Besserung im SPADI spürt der Patient etwas?", ["Etwa 8–13 Punkte", "1–2 Punkte", "Mindestens 40 Punkte", "Erst bei 0 Punkten"], 0, "Die kleinste spürbare Besserung im SPADI liegt bei etwa 8–13 Punkten."], ["Wie viele Beschwerdefreie haben einen Sehnenbefund im Ultraschall?", ["Fast niemand", "Etwa 34 %", "Etwa 90 %", "Nur Leistungssportler"], 1, "Etwa jeder Dritte ohne Beschwerden hat einen Sehnenbefund. Der Ultraschall allein erklärt den Schmerz deshalb nicht."]], "info": {"tendinopathie": {"t": "Tendinopathie", "x": ["Schmerzhafte Sehne mit veränderter Struktur und geringerer Belastbarkeit, meist ohne klassische Entzündung.", "Sie reagiert auf dosierte, steigende Last, nicht auf Schonung."], "q": "JOSPT 2025"}, "jospt": {"t": "JOSPT 2025", "x": ["Klinische Leitlinie der amerikanischen Physiotherapie-Fachgesellschaft zur Rotatorenmanschetten-Tendinopathie, Desmeules et al., April 2025.", "Grad A = starke Evidenz, F = Expertenmeinung."], "q": "Desmeules 2025"}, "s2e": {"t": "S2e-Leitlinie", "x": ["Deutsche Leitlinie „Subakromiales Impingement“ von DGOU und DVSE, 2021.", "Gültig bis 19.11.2026, also gerade abgelaufen. Sie ist chirurgisch geprägt und empfiehlt nach gescheiterter Physiotherapie noch die Dekompression."], "q": "AWMF 187-060"}, "windt": {"t": "van der Windt 1996", "x": ["349 neue Schulterschmerz-Episoden in niederländischen Hausarztpraxen.", "Nach 1 Monat 23 %, nach 1 Jahr 59 % erholt. Gilt für Schulterschmerz allgemein."], "q": "BJGP 1996"}, "star": {"t": "STAR-Shoulder", "x": ["Behandlungsmodell von McClure und Michener 2015: erst Reizbarkeit einstufen, dann die Intensität danach wählen.", "Laut den Autoren konzeptionell und nicht validiert."], "q": "Phys Ther 2015"}, "spadi": {"t": "SPADI", "x": ["Shoulder Pain and Disability Index: 13 Fragen zu Schmerz und Alltag, 0–100 Punkte, höher ist schlechter.", "Kleinste spürbare Besserung etwa 8–13 Punkte."], "q": "Fragebogen"}, "progressiv": {"t": "Progressives Krafttraining", "x": ["Die Last wird regelmäßig gesteigert, etwa alle zwei Wochen, sobald die Wiederholungen sauber gehen.", "In der JOSPT-Auswertung senkte es den Schmerz um gut einen Punkt auf der 10er-Skala."], "q": "JOSPT 2025"}, "holmgren": {"t": "Holmgren 2012", "x": ["102 Patienten auf der OP-Warteliste, Beschwerden über 6 Monate, alle bekamen erst eine Injektion.", "Exzentrische Übungen 3 × 15, 2× täglich bis Woche 8, dann 1× täglich bis Woche 12, Last alle 2 Wochen höher. Danach wollten nur 20 % operiert werden, in der Kontrollgruppe 63 %."], "q": "BMJ 2012"}, "ingwersen": {"t": "Ingwersen 2017", "x": ["100 Patienten, 12 Wochen schweres gegen leichtes progressives Training.", "Kein Unterschied in Funktion, Schmerz und Kraft."], "q": "OJSM 2017"}, "sad": {"t": "Subakromiale Dekompression", "x": ["Operation, bei der Knochen unter dem Schulterdach abgetragen wird.", "In CSAW und FIMPACT nach einem Jahr nicht besser als eine Schein-OP. Die BMJ-Empfehlung 2019 rät stark ab."], "q": "BMJ 2019"}}}, {"id": "w48-aha", "titel": "Schlaganfall-Reha: neue AHA-Leitlinie 2026", "art": "neu", "kb": "NE01", "min": 9, "abschnitte": [{"t": "1. Worum geht es?", "b": [{"p": ["Am 27.08.2026 haben die American Heart Association und die American Stroke Association in der Zeitschrift Stroke eine neue Leitlinie zur Rehabilitation nach Schlaganfall veröffentlicht (Richards et al.). Sie ersetzt die Fassung von 2016. Leiterin der Gruppe ist die Ergotherapeutin Lorie Gage Richards."]}, {"l": ["Neu oder überarbeitet sind vor allem Begleiterkrankungen, Frakturrisiko, Sturzvorbeugung, Unterstützung der Angehörigen, Teilhabe sowie die Rückkehr in Arbeit und ans Steuer.", "Die Telereha wird als wirksamer Weg für Behandlung zu Hause hervorgehoben.", "Für Physiotherapeuten gibt es eigene „Top Take-Home Messages“, verfasst von Alicen Whitaker-Hilbig aus der Leitliniengruppe."]}, {"fig": [{"src": "wissen/NE01.webp", "t": "Schlaganfall, Plakat aus Wissen › Krankheitsbilder.", "c": "Die Karte NE01 fasst Befund, Prognose und Behandlung zusammen. Die neue Leitlinie ergänzt sie."}]}]}, {"t": "2. Früh anfangen, aber nicht zu heftig", "b": [{"p": ["Die Reha soll im Krankenhaus beginnen, sobald der Patient medizinisch stabil ist, möglichst innerhalb von 48 Stunden. Lagewechsel und Mobilisation werden in den ersten 24–48 Stunden schrittweise gesteigert."]}, {"tab": [["Unter 24 Stunden", "keine mittel- bis hochintensiven Übungen und kein intensives Aufgabentraining"], ["Besonders vorsichtig", "schwer betroffene Patienten, Hirnblutung, eingeschränktes Bewusstsein"], ["Warum", "sehr frühe, intensive und lange Einheiten können den Kreislauf destabilisieren und das neurologische Ergebnis verschlechtern"]], "merk": "Früh heißt sanft: in den ersten 24 Stunden keine intensive Belastung, danach schrittweise mehr."}]}, {"t": "3. Gehen üben", "b": [{"l": ["Hoch dosiertes, aufgabenspezifisches Gehtraining ab der frühen subakuten Phase und weiter in der chronischen Phase verbessert das Gehen, ohne mehr schwere Zwischenfälle.", "Als Ergänzung genannt: Krafttraining, rhythmische akustische Signale, CIMT, Bewegungsvorstellung, Spiegeltherapie, Exergaming, funktionelle und sensible Elektrostimulation, Training im Wasser, Akupunktur und visuelles Biofeedback.", "Laufband mit Gewichtsentlastung und Gangroboter waren nicht besser als aufgabenspezifisches Gehtraining und sind teurer. Roboter können die Therapeuten körperlich entlasten.", "Fußheberschwäche: FES der Fußheber beim Gehen verbessert das Gehen ähnlich gut wie eine klassische Unterschenkelorthese (AFO)."], "merk": "Gehen lernt man durch Gehen, viel und gezielt. Technik ersetzt keine Wiederholungen."}]}, {"t": "4. Bewegung im Alltag und Messen", "b": [{"l": ["Ziel: mindestens 150 Minuten pro Woche moderates Ausdauertraining, dazu an 2–3 Tagen Kraft und Gleichgewicht. Die Leitlinie nennt 150–300 Minuten an 3–5 Tagen.", "Das Programm entsteht in der Reha und läuft zu Hause oder im Verein weiter. Ziele, Intensität, Häufigkeit und Dauer werden gemeinsam festgelegt.", "Im Alltag mehr stehen, gehen und Hausarbeit machen.", "Messen in der Praxis: Fugl-Meyer und ARAT für den Arm, modifizierte Ashworth-Skala für den Tonus, 10-m-Gehtest und 6-Minuten-Gehtest, Berg Balance Scale, Timed Up and Go, Functional Reach Test. Schrittzähler und Beschleunigungssensoren können den Alltag abbilden."]}]}, {"t": "5. Stürze, Knochen, Angehörige", "b": [{"l": ["Sturzrisiko so früh wie möglich einschätzen und jährlich wiederholen.", "Sturzvorbeugung: Aufklärung von Patient und Angehörigen, Wohnungsanpassung, Hilfsmittel und Orthesen, Gleichgewichtstraining wie Tai Chi, Dual-Task-Training und Exergaming. Sturzangst ansprechen, sie führt zu Inaktivität.", "Ausdauer, Kraft und Gleichgewicht können die Knochendichte verbessern und das Frakturrisiko senken.", "Bei Spastik sind Dehnprogramme sinnvoll, um Kontrakturen vorzubeugen. Überkopf-Seilzüge werden für Beweglichkeit und Schulterschmerz nicht empfohlen.", "In den USA helfen etwa 2,7 Millionen Angehörige. Sie sollen in Planung, Schulung und Unterstützung einbezogen werden.", "Ist ambulante Reha schwer erreichbar, sind Reha zu Hause und Telereha sinnvolle Alternativen."], "merk": "Sturzrisiko gleich am Anfang erfassen, Angehörige von Anfang an mitnehmen."}]}, {"t": "6. Was das für die Praxis heißt", "b": [{"l": ["Die Karte Schlaganfall (NE01) in Wissen › Krankheitsbilder passt zur neuen Leitlinie: aufgabenorientiertes Training, keine sehr frühe, hoch dosierte Mobilisation, Laufband mit Gewichtsentlastung und Gangroboter nicht besser.", "Für die Hausbesuche: Gehtraining im echten Alltag, Sturzrisiko, Wohnung und Angehörige gehören in jede Erstbefundung.", "Bewegungsziel von 150 Minuten pro Woche mit dem Patienten als realistischen Plan aufschreiben.", "Gehgeschwindigkeit im 10-m-Gehtest regelmäßig messen und dokumentieren."]}]}], "quellen": ["Richards LG et al. 2026 Guideline for Adult Stroke Rehabilitation and Recovery. Stroke 2026, doi 10.1161/STR.0000000000000536", "AHA/ASA: Top Take-Home Messages for Physical Therapists (Whitaker-Hilbig), 2026", "AHA Newsroom, 27.08.2026: Stroke rehab should start early and address physical, cognitive and mental health", "Stroke.org: Key recommendations, The Rehabilitation Program; Prevention and Medical Management of Comorbidities (2026)"], "fragen": [["Wann soll die Reha nach einem Schlaganfall laut AHA 2026 beginnen?", ["Sobald der Patient stabil ist, möglichst innerhalb von 48 Stunden", "Erst nach der Entlassung", "Frühestens nach 2 Wochen", "Sofort mit hoher Intensität in den ersten Stunden"], 0, "Die Reha beginnt im Krankenhaus, sobald der Patient medizinisch stabil ist, möglichst innerhalb von 48 Stunden."], ["Was soll in den ersten 24 Stunden nach einem Schlaganfall vermieden werden?", ["Lagewechsel", "Atemübungen", "Mittel- bis hochintensive Übungen", "Gespräch mit Angehörigen"], 2, "In den ersten 24 Stunden keine mittel- bis hochintensive Belastung. Sehr frühe, intensive Einheiten können den Kreislauf destabilisieren."], ["Bei welchen Patienten ist in der hyperakuten Phase besondere Vorsicht geboten?", ["Bei leicht Betroffenen", "Bei jungen Sportlern", "Bei Hirnblutung, schwerer Betroffenheit oder eingeschränktem Bewusstsein", "Bei Patienten mit Brille"], 2, "Die Leitlinie nennt schwer betroffene Patienten, intrazerebrale Blutung und verändertes Bewusstsein als besonders gefährdet."], ["Was sagt die Leitlinie zu Laufband mit Gewichtsentlastung und Gangroboter?", ["Beide sind dem Gehtraining klar überlegen", "Nicht besser als aufgabenspezifisches Gehtraining und teurer", "Nur Roboter sind sinnvoll", "Beide sind gefährlich"], 1, "Sie brachten keine besseren Gehergebnisse als aufgabenspezifisches Training. Roboter können aber die Therapeuten körperlich entlasten."], ["Wie schneidet FES der Fußheber im Vergleich zur Unterschenkelorthese ab?", ["Ähnlich gute Verbesserung des Gehens", "Deutlich schlechter", "Nur in der Akutphase besser", "FES wird nicht mehr empfohlen"], 0, "FES der Fußheber beim Gehen verbessert das Gehen ähnlich gut wie eine klassische AFO."], ["Welches Bewegungsziel nennt die Leitlinie?", ["30 Minuten pro Woche", "Täglich 2 Stunden Krafttraining", "Nur Gehen, kein Krafttraining", "Mindestens 150 Minuten moderates Ausdauertraining pro Woche plus 2–3 Tage Kraft und Gleichgewicht"], 3, "Mindestens 150 Minuten pro Woche moderat, dazu an 2–3 Tagen Kraft- und Gleichgewichtstraining."], ["Wann soll das Sturzrisiko erfasst werden?", ["Erst nach dem ersten Sturz", "Nur bei über 80-Jährigen", "So früh wie möglich, dann jährlich", "Nie, es ist nicht vorhersagbar"], 2, "Die Sturzrisikoeinschätzung soll so früh wie möglich erfolgen und jährlich wiederholt werden."], ["Was wird bei Schulterproblemen nach Schlaganfall ausdrücklich nicht empfohlen?", ["Lagerung", "Aufklärung", "Aktive Übungen im schmerzfreien Bereich", "Überkopf-Seilzüge"], 3, "Überkopf-Seilzüge werden nicht empfohlen, weder für die Beweglichkeit noch gegen Schulterschmerz."], ["Welche Rolle spielt die Telereha in der neuen Leitlinie?", ["Sinnvolle Alternative, wenn ambulante Reha schwer erreichbar ist", "Sie wird abgelehnt", "Sie ersetzt jede Präsenztherapie", "Sie ist nur für Sprachtherapie vorgesehen"], 0, "Wenn ambulante Reha begrenzt oder nicht erreichbar ist, sind Reha zu Hause und Telereha sinnvolle Alternativen."], ["Welche Fassung ersetzt die Leitlinie von 2026?", ["2006", "2016", "2021", "2024"], 1, "Die neue Leitlinie ersetzt die Fassung von 2016."]], "info": {}}, {"id": "w48-hue", "titel": "Koxarthrose", "art": "kb", "kb": "HU01", "min": 10, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Verschleiß des Hüftgelenks mit Knorpelverlust, Osteophyten und Kapselveränderung. Die Diagnose ist klinisch, ein Röntgenbild braucht es bei typischem Bild nicht."]}, {"l": ["17,9 % der Erwachsenen in Deutschland haben eine Arthrose, alle Gelenke zusammen (RKI GEDA).", "Weltweit 418 Hüftarthrosen je 100.000 Menschen, bis 2050 werden etwa 79 % mehr Fälle erwartet (GBD 2021).", "Risikofaktoren laut S2k-Leitlinie: Alter, Dysplasie, femoroazetabuläres Impingement, Trauma, Übergewicht, familiäre Belastung.", "Röntgenbefund und Beschwerden passen oft nicht zusammen."]}]}, {"t": "2. Typische Symptome und Verlauf", "b": [{"l": ["Leistenschmerz, oft bis zum Knie. Fast die Hälfte hat auch Schmerz unterhalb des Knies.", "Anlauf- und Belastungsschmerz, kurze Morgensteifigkeit.", "Innenrotation und Flexion sind früh eingeschränkt (Kapselmuster).", "Hinken, Schuhe und Socken anziehen fällt schwer."]}, {"bars": [["Röntgenarthrose am Anfang", 19, "CHECK-Kohorte"], ["Röntgenarthrose nach 10 Jahren", 49, "das Bild wird schlechter"], ["Noch Hüftschmerz nach 10 Jahren", 51, "Schmerz NRS im Mittel von 3,7 auf 2,9"], ["Prothese in 10 Jahren", 12, "etwa jeder Achte"]]}, {"p": ["Die Zahlen stammen aus der niederländischen CHECK-Kohorte (van Berkel 2021). Das Röntgenbild wird über Jahre meist schlechter, die Beschwerden oft nicht."], "merk": "Das Röntgenbild sagt wenig darüber, wie es dem Patienten geht."}, {"rot": "Ärztlich: Fieber und akut heißes Gelenk (septische Arthritis), plötzlicher Belastungsschmerz bei Osteoporose (Stress- oder Insuffizienzfraktur), Kortison, Alkohol oder Sichelzellerkrankung in der Vorgeschichte (Hüftkopfnekrose), Ruhe- und Nachtschmerz mit Gewichtsverlust."}]}, {"t": "3. Befund und Abgrenzung", "b": [{"l": ["Passive Innenrotation und Flexion im Seitenvergleich.", "Scour-Test, Schmerz in der Hocke, Schmerz bei aktiver Flexion und Extension.", "Gangbild, Trendelenburg, Kraft der Hüftabduktoren und -extensoren.", "LWS und Trochanter mit untersuchen."]}, {"p": ["[[ACR-Kriterien|acr]]: Hüftschmerz plus Innenrotation unter 15° und weitere Merkmale, klinisch Sensitivität 86 %, Spezifität 75 %. Im [[Sutlive-Cluster|sutlive]] machen 4 von 5 positiven Zeichen eine Arthrose sehr wahrscheinlich (LR+ 24,3, aber mit sehr breitem Konfidenzintervall und nicht validiert)."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-trendelenburg.webp", "t": "Einbeinstand rechts, Ansicht von hinten.", "c": "Links normal: Der rechte Gluteus medius hält das Becken waagerecht. Rechts Trendelenburg-Zeichen: Der Muskel ist schwach, das Becken sinkt zur Seite des angehobenen Beins ab."}]}, {"tab": [["Gluteale Tendinopathie", "Schmerz seitlich am Trochanter, Liegen auf der Seite"], ["Lumbale Radikulopathie", "Dermatom, Neurologie, LWS-Bewegung provoziert"], ["FAI, Labrum", "jünger, Leiste, Blockaden"], ["Hüftkopfnekrose", "Kortison, Alkohol, rascher Verlauf. MRT, ärztlich"], ["Leistenhernie, Bauch", "Husten, Pressen, Bauchsymptome"]]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."]}]}, {"t": "4. Messen", "b": [{"tab": [["Timed Up and Go", "spürbar 0,8–1,4 s schneller"], ["40-m-Gehtest", "0,2–0,3 m/s schneller"], ["30-s-Chair-Stand", "2–2,6 Wiederholungen mehr"], ["20-cm-Stufentest", "5–16 Stufen mehr"]], "p": ["Die Schwellen stammen aus Wright 2011. Für HOOS, WOMAC und NPRS ließ sich bei Hüftarthrose kein MCID belegen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"p": ["Die S2k-Leitlinie Koxarthrose von 2019 ist abgelaufen und in Überarbeitung, die S3-Leitlinie zur Hüftprothese ([[EKIT-Hüfte|ekit]]) seit 03/2026 ebenfalls. Einig sind sich alle Leitlinien (NICE, EULAR, JOSPT, ACR, OARSI): Schulung, Bewegungstherapie und bei Übergewicht Abnehmen zuerst."]}, {"l": ["Übungstherapie ist überall erste Wahl, kein Übungstyp ist überlegen.", "Der Effekt ist eher klein: Schmerz etwa 7 von 100 Punkten besser als keine Behandlung, spürbar wären etwa 12 ([[Cochrane 2026|cochrane]]).", "GLA:D Hüfte: Schmerz nach 3 Monaten 11 von 100 Punkten besser, allerdings Registerdaten ohne Kontrollgruppe.", "Kraft für Hüftabduktoren und -extensoren, Sit-to-Stand, 3 × 10–12, steigend. Ausdauer 15–30 min auf dem Ergometer, beim Gehen oder im Wasser.", "Manuelle Therapie: Hoeksma 2004 positiv, in der Studie mit Scheinbehandlung (Bennell 2014) kein Zusatznutzen und mehr Nebenwirkungen. Nur zusammen mit Übungen.", "Prähabilitation vor der TEP verbessert die Leistungstests nach der OP, kaum den Schmerz."]}, {"tab": [["Nicht empfohlen", "TENS, Ultraschall, Elektrotherapie, Hyaluronsäure"], ["TEP-Indikation (EKIT)", "Kellgren-Lawrence 3 oder 4, hoher Leidensdruck trotz mindestens 3 Monaten konservativer Therapie, andere Ursachen ausgeschlossen"]], "merk": "Schmerz beim Training bis 5 von 10 ist erlaubt, wenn er am nächsten Morgen zurück auf dem gewohnten Niveau ist (Expertenmeinung)."}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Schulung in jeder Einheit: Bewegung schützt das Gelenk, Schmerz heißt nicht Schaden.", "Am Anfang 30-s-Chair-Stand und TUG messen, nach 6 Wochen wiederholen.", "Programm 6–12 Wochen, 2× pro Woche plus Heimprogramm.", "Nach einer Kortisonspritze mindestens 6 Wochen, besser 3 Monate bis zur OP.", "Vor der TEP Gehhilfen üben und den Ablauf nach der OP erklären."], "merk": "Fürs Patientengespräch: „Das Röntgenbild sagt wenig darüber, wie es Ihnen geht. Training für Kraft und Ausdauer ist die wichtigste Behandlung, und ein bisschen Schmerz beim Üben ist erlaubt.“"}]}], "quellen": ["S2k Koxarthrose, AWMF 033-001, 2019, abgelaufen, in Überarbeitung", "S3 EKIT-Hüfte, AWMF 187-001, 2021, gültig bis 23.03.2026, in Überarbeitung", "NICE NG226 2022; EULAR 2024; JOSPT CPG Hip OA Revision 2025; ACR 2019; OARSI 2019", "Cochrane 2026 (Übungen bei Hüftarthrose, CD007912.pub3); Skou & Roos 2017 (GLA:D)", "Hoeksma 2004; Bennell JAMA 2014; Altman 1991; Sutlive 2008; van Berkel 2021 (CHECK); Wright JOSPT 2011; GBD 2021; RKI GEDA"], "fragen": [["Welche Bewegung ist bei Koxarthrose typischerweise zuerst eingeschränkt?", ["Extension", "Adduktion", "Außenrotation", "Innenrotation"], 3, "Das Kapselmuster der Hüfte: Innenrotation vor Flexion vor Abduktion."], ["Was gehört zu den klinischen ACR-Kriterien?", ["Leistenschmerz nur beim Husten", "Positiver Lasègue", "Innenrotation unter 15°", "Alter unter 30"], 2, "Hüftschmerz plus Innenrotation unter 15° und weitere Merkmale wie Alter über 50 und Morgensteifigkeit."], ["Braucht es bei typischem klinischem Bild ein Röntgen für die Diagnose?", ["Ja, immer", "Nur ein MRT", "Nur bei Männern", "Nein, die Diagnose ist klinisch"], 3, "Die Diagnose ist klinisch. Röntgen braucht es bei atypischem Bild oder vor einer OP."], ["Was zeigt das rechte Bild?", ["Duchenne-Hinken bei Spastik", "Trendelenburg-Zeichen bei schwachem Gluteus medius", "Beinlängendifferenz", "Normaler Einbeinstand"], 1, "Das Becken sinkt zur Seite des angehobenen Beins. Schwach ist der Gluteus medius des Standbeins.", "fortbildung/bilder/2026-W47/ana-hue-trendelenburg.webp"], ["Wie groß ist der Effekt von Übungen auf den Schmerz laut Cochrane 2026 etwa?", ["Etwa 50 von 100 Punkten", "Gar keiner", "Etwa 7 von 100 Punkten", "Etwa 30 von 100 Punkten"], 2, "Etwa 7 von 100 Punkten besser als keine Behandlung. Spürbar wären etwa 12."], ["Was gilt im 30-s-Chair-Stand als spürbare Besserung?", ["Eine halbe Wiederholung", "Mindestens 10 Wiederholungen mehr", "Nur die Zeit zählt", "Etwa 2–2,6 Wiederholungen mehr"], 3, "Nach Wright 2011 sind 2–2,6 Wiederholungen mehr spürbar."], ["Was zeigte Bennell 2014 zur manuellen Therapie bei Hüftarthrose?", ["Großer Zusatznutzen", "Kein Zusatznutzen gegenüber Scheinbehandlung, mehr Nebenwirkungen", "Nur Traktion hilft", "Besser als jede Übung"], 1, "In der Studie mit Scheinbehandlung brachte die aktive Physiotherapie mit manueller Therapie keinen Zusatznutzen."], ["Wann ist laut EKIT-Hüfte eine Prothese angezeigt?", ["Bei jedem Leistenschmerz", "Sobald das Röntgen einen Osteophyten zeigt", "Bei Kellgren-Lawrence 3–4, hohem Leidensdruck und mindestens 3 Monaten konservativer Therapie", "Nur unter 50 Jahren"], 2, "Strukturschaden 3–4, hoher Leidensdruck trotz mindestens 3 Monaten leitliniengerechter konservativer Therapie und andere Ursachen ausgeschlossen."], ["Wie viele bekamen in der CHECK-Kohorte in 10 Jahren eine Hüft-TEP?", ["Etwa 50 %", "Etwa 12 %", "Fast alle", "Niemand"], 1, "Etwa jeder Achte, 12 %. Das Röntgenbild wurde schlechter, der Schmerz blieb im Mittel stabil."], ["Welche Maßnahme wird bei Hüftarthrose nicht empfohlen?", ["TENS", "Schulung", "Krafttraining", "Abnehmen bei Übergewicht"], 0, "TENS, Ultraschall, Elektrotherapie und Hyaluronsäure werden nicht empfohlen."], ["Was ist ein Warnzeichen, das ärztlich abgeklärt werden muss?", ["Fieber mit akut heißem Hüftgelenk", "Anlaufschmerz am Morgen", "Schmerz beim Socken anziehen", "Leichtes Hinken nach langem Gehen"], 0, "Fieber und akut heißes Gelenk können eine septische Arthritis sein."], ["Wie lange sollte nach einer Kortisonspritze bis zur Hüft-TEP mindestens vergehen?", ["Mindestens 6 Wochen, besser 3 Monate", "1 Tag", "1 Jahr", "Gar keine Pause"], 0, "Zwischen Kortisonspritze und OP mindestens 6 Wochen, besser 3 Monate."]], "info": {"acr": {"t": "ACR-Kriterien (Altman 1991)", "x": ["Klinische Kriterien der Hüftarthrose: Hüftschmerz plus Innenrotation unter 15° und weitere Merkmale (Alter über 50, Morgensteifigkeit, Schmerz bei Innenrotation).", "Klinisch Sensitivität 86 %, Spezifität 75 %; mit Röntgen 89 % und 91 %."], "q": "Altman 1991"}, "sutlive": {"t": "Sutlive-Cluster", "x": ["5 Zeichen: Scour-Test, passive Innenrotation höchstens 25°, Schmerz in der Hocke, Schmerz bei aktiver Flexion, Schmerz bei aktiver Extension.", "4 von 5 positiv: LR+ 24,3 (KI 4,4–142,1); 3 von 5: LR+ 5,2, LR− 0,33. Kleine Studie, nicht validiert."], "q": "Sutlive 2008"}, "ekit": {"t": "EKIT-Hüfte", "x": ["S3-Leitlinie zur Indikation der Hüft-TEP, AWMF 187-001, 2021, seit 03/2026 abgelaufen, in Überarbeitung.", "TEP bei Kellgren-Lawrence 3–4, hohem Leidensdruck und mindestens 3 Monaten erfolgloser konservativer Therapie."], "q": "AWMF 187-001"}, "cochrane": {"t": "Cochrane 2026", "x": ["Update zu Übungen bei Hüftarthrose: 18 Studien, 1368 Teilnehmende.", "Schmerz etwa 7 von 100 Punkten besser als keine Behandlung, gegen Schein-Behandlung noch weniger."], "q": "CD007912.pub3"}}}]});
